WITH inner_cte AS ( SELECT s.TIP_SUBJECT_OFFERED_KEY, s.SUBJECT_TITLE, s.OFFER_DEPT_NAME, t.TERM_DESCRIPTION, RANK() OVER (PARTITION BY s.OFFER_DEPT_NAME ORDER BY s.TIP_SUBJECT_OFFERED_KEY) AS subject_rank_in_dept, l.COURSE_NUMBER, l.COURSE_NUMBER_DESC, l.NUM_ENROLLED_STUDENTS, d.LIBRARY_RESERVE_CATALOG_KEY, DENSE_RANK() OVER (PARTITION BY d.LIBRARY_MATERIAL_STATUS_KEY ORDER BY d.LIBRARY_MATERIAL_STATUS_KEY) AS dense_rank_material_status, s.SUBJECT_ID, t.TERM_CODE FROM TIP_SUBJECT_OFFERED s JOIN ACADEMIC_TERMS t ON s.TERM_CODE = t.TERM_CODE JOIN ACADEMIC_TERM_PARAMETER p ON t.TERM_CODE = p.TERM_CODE JOIN LIBRARY_SUBJECT_OFFERED l ON s.SUBJECT_ID = l.SUBJECT_ID JOIN LIBRARY_RESERVE_MATRL_DETAIL d ON l.SUBJECT_ID = d.SUBJECT_ID WHERE t.TERM_DESCRIPTION = 'Fall Term 2024-2025' AND l.NUM_ENROLLED_STUDENTS > 0 AND d.LIBRARY_MATERIAL_STATUS_KEY = 'U' ) SELECT i.TIP_SUBJECT_OFFERED_KEY, i.SUBJECT_TITLE, i.OFFER_DEPT_NAME, i.TERM_DESCRIPTION, i.subject_rank_in_dept, i.COURSE_NUMBER, i.COURSE_NUMBER_DESC, i.NUM_ENROLLED_STUDENTS, i.LIBRARY_RESERVE_CATALOG_KEY, i.dense_rank_material_status, t.TERM_START_DATE, t.TERM_END_DATE FROM inner_cte i JOIN ACADEMIC_TERMS t ON i.TERM_CODE = t.TERM_CODE ORDER BY i.TIP_SUBJECT_OFFERED_KEY, i.COURSE_NUMBER;